#!/usr/bin/env python3
"""Merge user records from JSON, CSV, and Parquet sources."""

from __future__ import annotations

import json
from datetime import date, datetime
from pathlib import Path
from typing import Any

import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq

SOURCES = [
    ("source_a", Path("/data/source_a/users.json")),
    ("source_b", Path("/data/source_b/users.csv")),
    ("source_c", Path("/data/source_c/users.parquet")),
]

# Unified field name -> accepted source field names, in lookup order.
FIELD_ALIASES = {
    "user_id": ["user_id", "id", "userId"],
    "name": ["full_name", "name", "userName"],
    "email": ["email", "email_address"],
    "created_date": ["registration_date", "created_at", "joined"],
    "status": ["status", "is_active", "active"],
}

OUTPUT_FIELDS = ["name", "email", "created_date", "status"]


def read_source(path: Path) -> list[dict[str, Any]]:
    suffix = path.suffix.lower()
    if suffix == ".json":
        with path.open("r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            data = [data]
        return data
    if suffix == ".csv":
        return pd.read_csv(path).to_dict(orient="records")
    if suffix == ".parquet":
        return pd.read_parquet(path).to_dict(orient="records")
    raise ValueError(f"Unsupported source format: {path}")


def is_blank(value: Any) -> bool:
    if value is None:
        return True
    if isinstance(value, float) and pd.isna(value):
        return True
    try:
        return bool(pd.isna(value))
    except (TypeError, ValueError):
        return False


def normalize_date(value: Any) -> str | None:
    if is_blank(value):
        return None
    if isinstance(value, (datetime, date, pd.Timestamp)):
        return value.strftime("%Y-%m-%d")
    # pandas handles common representations (including ISO datetimes).
    parsed = pd.to_datetime(value, errors="coerce")
    if pd.isna(parsed):
        return str(value)
    return parsed.strftime("%Y-%m-%d")


def normalize_status(value: Any) -> str | None:
    if is_blank(value):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    if isinstance(value, (int, float)) and value in (0, 1):
        return "active" if bool(value) else "inactive"
    text = str(value).strip()
    if text.lower() in {"true", "1", "yes", "y", "active"}:
        return "active"
    if text.lower() in {"false", "0", "no", "n", "inactive"}:
        return "inactive"
    return text


def normalize_source(name: str, records: list[dict[str, Any]]) -> dict[int, dict[str, Any]]:
    normalized: dict[int, dict[str, Any]] = {}
    for raw in records:
        record: dict[str, Any] = {}
        for field, aliases in FIELD_ALIASES.items():
            value = next(
                (raw[alias] for alias in aliases if alias in raw and not is_blank(raw[alias])),
                None,
            )
            if field == "user_id":
                value = int(value) if value is not None else None
            elif field == "created_date":
                value = normalize_date(value)
            elif field == "status":
                value = normalize_status(value)
            elif value is not None:
                value = str(value)
            record[field] = value

        user_id = record["user_id"]
        if user_id is None:
            raise ValueError(f"Missing user id in {name}: {raw}")
        if user_id in normalized:
            raise ValueError(f"Duplicate user id {user_id} in {name}")
        normalized[user_id] = record
    return normalized


def main() -> None:
    source_records: dict[str, dict[int, dict[str, Any]]] = {}
    for source_name, path in SOURCES:
        source_records[source_name] = normalize_source(source_name, read_source(path))

    all_user_ids = sorted(
        {user_id for records in source_records.values() for user_id in records}
    )

    merged_rows: list[dict[str, Any]] = []
    conflicts: list[dict[str, Any]] = []

    for user_id in all_user_ids:
        row: dict[str, Any] = {"user_id": user_id}

        for field in OUTPUT_FIELDS:
            # Gather values from all sources where this field is present.
            values = {
                source_name: records[user_id][field]
                for source_name, records in source_records.items()
                if user_id in records and records[user_id][field] is not None
            }

            # Highest-priority non-null value wins (source_a > source_b > source_c).
            selected = next(
                (
                    records[user_id][field]
                    for source_name, records in source_records.items()
                    if user_id in records and records[user_id][field] is not None
                ),
                None,
            )
            row[field] = selected

            if len(set(values.values())) > 1:
                conflicts.append(
                    {
                        "user_id": user_id,
                        "field": field,
                        "values": {
                            source_name: values.get(source_name)
                            for source_name, _ in SOURCES
                        },
                        "selected": selected,
                    }
                )

        merged_rows.append(row)

    schema = pa.schema(
        [
            ("user_id", pa.int64()),
            ("name", pa.string()),
            ("email", pa.string()),
            ("created_date", pa.string()),
            ("status", pa.string()),
        ]
    )
    table = pa.Table.from_pylist(merged_rows, schema=schema)
    pq.write_table(table, "/app/merged_users.parquet")

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2, ensure_ascii=False)
        f.write("\n")

    print(f"Merged {len(merged_rows)} users with {len(conflicts)} conflicts.")


if __name__ == "__main__":
    main()
